INSERT INTO public."AnalysisStep" VALUES ('cmumtrvxt000ci3tiy3reyehp', 'fa1fdb34-4207-4e81-8162-b3c073155cc3', 'market_regime', 7, '市场状态 Agent', 'completed', '2026-09-29 15:22:46.337', '2026-09-29 15:22:51.21', 4873, 'trending_up · 同意规则判定 trending_up：截至 2026-09-29T15:22:26Z 的快照中，1h/4h/1d 均为 up、EMA 排列 bullish、趋势一致性 1.00（ev:regime、e', '{"label": "trending_up", "summary": "同意规则判定 trending_up：截至 2026-09-29T15:22:26Z 的快照中，1h/4h/1d 均为 up、EMA 排列 bullish、趋势一致性 1.00（ev:regime、ev:alignment、ev:trend:1h、ev:trend:4h、ev:trend:1d）。保留意见有两点：一是短周期动能与趋势不同步，1h MACD 柱略为负且 1/5/20 根收益率均为负，说明最近数小时为高位停滞而非加速（ev:momentum:1h、ev:volume:1h）；二是 1d 波动率为 high、布林带宽分位 89 且 %B=0.99，价格贴近上轨，属高波动扩张，方向上仍为上行但路径不确定性偏高（ev:vol:1d、ev:vol:4h）。因此定性为“上行趋势 + 短周期动量停滞 + 日线高波动”，而非低波动稳定趋势。参考价 0.2305 紧邻 1h 阻力 0.2307，上方 0.2345、0.2371；下方支撑 0.2225、0.2157（lv:1h:3、lv:1h:4、lv:1h:5、lv:4h:0、lv:1h:0）。快照价格高于用户观察区间上限 0.22，需下跌约 4.56% 才进入（ev:target_range，该区间为用户观察区间，非止损止盈或持仓成本）。新闻、社交情绪、链上数据、资金费率、持仓量均未接入；量化预测为 unavailable，本次仅为技术面状态判断，不含概率或价格目标（ev:prediction）。", "evidenceIds": ["ev:regime", "ev:alignment", "ev:trend:1h", "ev:trend:4h", "ev:trend:1d", "ev:momentum:1h", "ev:momentum:4h", "ev:momentum:1d", "ev:vol:1h", "ev:vol:4h", "ev:vol:1d", "ev:volume:1h", "ev:volume:4h", "ev:volume:1d", "lv:1h:3", "lv:1h:4", "lv:1h:5", "lv:4h:0", "lv:1h:0", "lv:4h:1", "ev:target_range", "ev:prediction"], "effectOnSignals": "趋势类信号在 4h/1d 上更有效：三周期 EMA 排列均为 bullish，EMA50 斜率 1.52%/2.04%/6.12%，多周期一致性得分 1.00，且 4h/1d 收益与量能同向（4h 1/5/20 根收益率 +1.34%/+5.85%/+6.67%，1d +7.74%/+15.04%/+23.87%；1d 成交量相对 20 根均量 158.08%），回撤型逆势信号在趋势方向上容错较低。均值回归类信号可信度分层：1h 层面动量已停滞（MACD 柱 -0.0000，1/5/20 根收益率 -0.82%/-0.43%/-0.17%，成交量相对均量仅 19.03%），区间上沿附近的反转信号缺乏短周期动能支持；但 4h %B=1.01、1d %B=0.99、1d 布林带宽 36.02%（分位 89）显示价格贴近布林上轨并处于高波动扩张，此类位置的均值回归信号易被波动放大击穿，需以波动率与支撑位为参照，而非单纯依赖超买读数。"}', NULL, '{ev:regime,ev:alignment,ev:trend:1h,ev:trend:4h,ev:trend:1d,ev:momentum:1h,ev:momentum:4h,ev:momentum:1d,ev:vol:1h,ev:vol:4h,ev:vol:1d,ev:volume:1h,ev:volume:4h,ev:volume:1d,lv:1h:3,lv:1h:4,lv:1h:5,lv:4h:0,