INSERT INTO public."AnalysisStep" VALUES ('cmumtrvxq000bi3timwwv98xz', 'fa1fdb34-4207-4e81-8162-b3c073155cc3', 'technical_analyst', 6, '技术分析 Agent', 'completed', '2026-09-29 15:22:29.522', '2026-09-29 15:22:46.296', 16774, '技术面呈多周期上行趋势（一致性得分 1.00），4h/1d 动量与量能为正、1d 成交量显著放大，但 1h 动量（MACD 柱略负、1/5/20 根收益率为负）与短周期量能（相对均量 19.03%）显示上行动能在最近数小时停滞。价格 0.2', '{"trend": "多周期趋势一致向上：1h/4h/1d 的 EMA 排列均为 bullish，EMA50 斜率分别为 1.52%、2.04%、6.12%，多周期一致性得分 1.00。收盘价 0.2305（1h）/0.2336（4h）/0.2325（1d）均在各自 EMA20、EMA50、EMA200 之上，1d EMA20 0.2033 高于 EMA50 0.1915 与 EMA200 0.1906，呈多头排列。上方近端阻力为 0.2307（1h，距当前 0.09%）、0.2345（1h，1.76%）、0.2371（1h，2.86%），更上方为 0.2520（1d，8.39%）。下方支撑依次为 0.2225（4h，-4.75%）、0.2157（1h，-6.43%）、0.1992（1h，-13.60%）、0.1891（4h，-19.06%）。", "volume": "大周期量能明显放大：1d 最近一根成交量相对 20 根均量为 158.08%，4h 为 20.80%，与 4h/1d 的正向收益相配合；1h 最近一根成交量相对 20 根均量仅 19.03%，短周期量能未同步扩张。", "summary": "技术面呈多周期上行趋势（一致性得分 1.00），4h/1d 动量与量能为正、1d 成交量显著放大，但 1h 动量（MACD 柱略负、1/5/20 根收益率为负）与短周期量能（相对均量 19.03%）显示上行动能在最近数小时停滞。价格 0.2305 紧邻 1h 阻力 0.2307，上方另见 0.2345、0.2371；下方支撑 0.2225、0.2157。1d 波动率处于高位且价格接近布林上轨。快照价格高于用户目标区间上限 0.22，需下跌约 4.56% 才进入该区间（该区间为用户观察区间，非止损止盈或持仓成本）。新闻、社交情绪、链上数据、资金费率与持仓量均未接入；量化预测为 unavailable，本次仅提供技术分析。", "momentum": "动量呈大周期强、小周期转弱的层级差异。1d RSI14=68.5、MACD 柱=+0.0031，4h RSI14=64.9、MACD 柱=+0.0016，均处正向；1h RSI14=56.1，但 MACD 柱=-0.0000（MACD 0.0029/信号 0.0030），已略转负。收益结构同样分层：1d 的 1/5/20 根收益率为 7.74%/15.04%/23.87%，4h 为 1.34%/5.85%/6.67%，而 1h 为 -0.82%/-0.43%/-0.17%，显示最近数小时动能停滞而非延续。", "conflicts": ["1h MACD 柱略为负（-0.0000），与 4h/1d 的正 MACD 柱及三周期 EMA 多头排列形成短周期动量冲突。", "1h 的 1/5/20 根收益率均为负（-0.82%/-0.43%/-0.17%），与 4h（+1.34%/+5.85%/+6.67%）、1d（+7.74%/+15.04%/+23.87%）的正收益方向不一致。", "4h %B=1.01、1d %B=0.99 显示价格位于布林上轨附近，而 1h %B=0.665，短周期未同步处于超买边缘。", "波动率层级差异明显：1d 为 high、布林带宽分位 89，1h 为 normal，短周期波动率读数与日线高波动状态不匹配。"], "volatility": "波动率由短到长递增：1h ATR14=2.05%、布林带宽 4.83%、%B=0.665；4h ATR14=3.46%、布林带宽 12.68%、%B=1.01；1d ATR14=5.86%、布林带宽 36.02%、%B=0.99。1d 波动率为 high、布林带宽分位 89，价格贴近或略超上轨，属高波动扩张状态；1h 为 normal 且 %B 未达上轨。", "evidenceIds": ["ev:trend:1h", "ev:trend:4h", "ev:trend:1d", "ev:momentum:1h", "ev:momentum:4h", "ev:momentum:1d", "ev:vol:1h", "ev:vol:4h", "ev:vol:1d", "ev:volume:1h", "ev:volume:4h", "ev:volume:1d", "ev:regime", "ev:alignment", "ev:target_range", "ev:prediction", "lv:1h:3", "lv:1h:4", "lv:1h:5", "lv:1d:3", "lv:4h:0", "lv:1h:0", "lv:1h:1", "lv:4h:1"]}', NULL, '{ev:trend:1h,ev:trend:4h,ev:trend:1d,ev:momentum:1h,ev:momentum:4h,ev:momentum:1d,ev:vol:1h,ev:vol:4h,ev:vol:1d,ev:volume:1h,ev:volume:4h,ev:volume:1d,ev:regime,ev:alignment,ev:target_range,ev:prediction,lv:1h:3,lv:1h:4,lv:1h:5,lv:1d:3,lv:4h:0,lv:1h:0,lv:1h:1,lv:4h:1}');
