INSERT INTO public."AnalysisStep" VALUES ('cmumubrp3000y38tigsv6jyzu', '7ffcd273-d3ff-4d57-a436-3450bce790a9', 'market_regime', 7, '市场状态 Agent', 'completed', '2026-09-29 15:38:10.881', '2026-09-29 15:38:15.802', 4921, 'trending_up · 同意规则判定 trending_up：1h/4h/1d 趋势方向一致向上，EMA 排列 bullish，长周期斜率更陡，1d 放量（相对 20 根均量 158.08%）且动量偏强（RSI14 68.5', '{"label": "trending_up", "summary": "同意规则判定 trending_up：1h/4h/1d 趋势方向一致向上，EMA 排列 bullish，长周期斜率更陡，1d 放量（相对 20 根均量 158.08%）且动量偏强（RSI14 68.5、MACD 柱 0.0031）。保留意见有两点：其一，1h 动量转弱（MACD 柱刚转负、RSI14 56.1）且短周期收益率为负、缩量，与 4h/1d 方向相反，说明该上行趋势在短周期未获确认；其二，1d 波动率处高位（ATR14 5.86%、带宽 36.02%、带宽分位 89）且 4h/1d 价格贴近布林上轨（%B 1.01/0.99），状态具备向高位波动或震荡过渡的条件，而非低波动的稳健单边上行。上方阻力 0.2307、0.2345，下方支撑 0.2225、0.2157。本结论基于数据截止 2026-09-29T15:37:55.062Z 的历史快照，非实时行情。", "evidenceIds": ["ev:regime", "ev:alignment", "ev:trend:1h", "ev:trend:4h", "ev:trend:1d", "ev:momentum:1h", "ev:momentum:4h", "ev:momentum:1d", "ev:vol:1h", "ev:vol:4h", "ev:vol:1d", "ev:volume:1h", "ev:volume:4h", "ev:volume:1d", "lv:4h:0", "lv:1h:0", "lv:1h:3", "lv:1h:4", "ev:prediction"], "effectOnSignals": "趋势类信号：多周期方向一致（1h/4h/1d 均为 up，一致性得分 1.00），EMA 多头排列且长周期 EMA50 斜率更陡（1h 1.52%、4h 2.04%、1d 6.12%），顺势型趋势跟随信号在此环境下相对占优；但短周期已出现背离——1h RSI14 回落至 56.1、MACD 柱 -0.0000、1/5/20 根收益率为 -0.82%/-0.43%/-0.17%、成交量为 20 根均量的 19.03%，因此 1h 级别趋势信号噪声占比偏高，方向确认权重宜低于 4h/1d。均值回归类信号：4h 与 1d 的 %B 分别为 1.01 与 0.99，价格贴近布林上轨，1d 带宽 36.02%、带宽分位 89、ATR14 5.86%，波动率处高位，逆势回归信号（如以上轨为卖点）缺乏均值回归所需的震荡前提，失败风险偏高；仅在价格回落至 4h 支撑 0.2225 或 1h 支撑 0.2157 且该位置未被有效跌破时，回归型信号才具参考条件。近端阻力 0.2307（+0.09%）与 0.2345（+1.76%）距离极近，突破型信号需关注是否有效突破而非瞬时触及。预测模型不可用，不应以模型信心替代概率。新闻、社交情绪、链上数据、资金费率、持仓量均未接入。"}', NULL, '{ev:regime,ev:alignment,ev:trend:1h,ev:trend:4h,ev:trend:1d,ev:momentum:1h,ev:momentum:4h,ev:momentum:1d,ev:vol:1h,ev:vol:4h,ev:vol:1d,ev:volume:1h,ev:volume:4h,ev:volume:1d,lv:4h:0,lv:1h:0,lv:1h:3,lv:1h:4,ev:prediction}');
