INSERT INTO public."AnalysisStep" VALUES ('cmumusggh000djsti4y0vzwx7', 'b30258dc-5563-4547-98a9-d17b1a01db78', 'technical_analyst', 6, '技术分析 Agent', 'completed', '2026-09-29 15:50:53.916', '2026-09-29 15:50:59.851', 5935, '历史快照（截止 2026-09-29T15:50:52Z）显示 XLMUSDT 处于多周期上行趋势，4h/1d 动量与日线放量支持该结构；但 1h 动量转平、近 1/5/20 根收益小幅为负，短周期与中长周期存在冲突，且 4h/1d 价格已', '{"trend": "多周期一致上行（一致性得分 1.00）：1h/4h/1d 均为 up 且 EMA 排列 bullish，1d EMA50 斜率 6.12% 最强，价格位于 1h EMA20/50/200 之上，属趋势性上涨结构。", "volume": "分化明显：1d 最近一根成交量为 20 根均量的 158.08%，配合 1/5/20 根收益 +7.74%/+15.04%/+23.87%，属放量上行；1h 与 4h 仅约 19%–21%，短周期量能跟进不足。", "summary": "历史快照（截止 2026-09-29T15:50:52Z）显示 XLMUSDT 处于多周期上行趋势，4h/1d 动量与日线放量支持该结构；但 1h 动量转平、近 1/5/20 根收益小幅为负，短周期与中长周期存在冲突，且 4h/1d 价格已贴近布林上轨、日线波动率处高分位，追涨风险偏高。上方近端阻力 0.2307/0.2345/0.2371，下方支撑 0.2225（-4.75%）与 0.2157（-6.43%）；快照价 0.2305 高于用户观察区间上限 0.22。量化预测不可用，新闻、情绪、链上、资金费率与持仓量均未接入。", "momentum": "4h MACD 柱 0.0016、1d 柱 0.0031 均为正，趋势动量仍在；但 1d RSI 68.5、4h RSI 64.9 已偏高，1h RSI 56.1 中性且 MACD 柱轻微转负，短周期动量先行钝化。", "conflicts": ["1h 收益率 1/5/20 根分别为 -0.82%/-0.43%/-0.17%，与 4h、1d 的正收益方向相悖，短周期出现回吐。", "1h MACD 柱轻微转负、RSI 56.1，与 4h/1d 的正 MACD 柱及 64.9/68.5 的 RSI 形成动量背离。", "4h %B=1.01、1d %B=0.99，价格贴近或超出布林上轨，与 1h %B=0.66 的中性位置不一致。", "日线放量（158%）与 1h/4h 缩量（约 19%–21%）并存，量价配合在短周期未被确认。", "1d 波动率处高分位（带宽分位 89），而 1h/4h 波动率被判定为 normal。"], "volatility": "日线波动率高：1d ATR14 为 5.86%，布林带宽 36.02% 处布林带宽分位 89，20 根实现波动率 4.77%；1h（ATR 2.05%）与 4h（3.46%）相对温和。", "evidenceIds": ["ev:alignment", "ev:regime", "ev:momentum:1h", "ev:momentum:4h", "ev:momentum:1d", "ev:volume:1d", "ev:volume:1h", "ev:vol:1d", "lv:4h:0", "ev:target_range"]}', NULL, '{ev:alignment,ev:regime,ev:momentum:1h,ev:momentum:4h,ev:momentum:1d,ev:volume:1d,ev:volume:1h,ev:vol:1d,lv:4h:0,ev:target_range}');
