ignment": {"agree": true, "score": 1, "detail": "1h:up, 4h:up, 1d:up"}}', NULL, '{ev:trend:1h,ev:momentum:1h,ev:vol:1h,ev:volume:1h,ev:trend:4h,ev:momentum:4h,ev:vol:4h,ev:volume:4h,ev:trend:1d,ev:momentum:1d,ev:vol:1d,ev:volume:1d,lv:4h:0,lv:1h:0,lv:1h:1,lv:1h:2,lv:4h:1,lv:1h:3,lv:1h:4,lv:1h:5,lv:1d:3,lv:1d:4,ev:regime,ev:alignment,ev:target_range}');
INSERT INTO public."AnalysisStep" VALUES ('cmumusggj000ejstindrwn9nw', 'b30258dc-5563-4547-98a9-d17b1a01db78', 'market_regime', 7, '市场状态 Agent', 'completed', '2026-09-29 15:50:59.881', '2026-09-29 15:51:03.824', 3943, 'trending_up · 同意规则标签 trending_up：1h/4h/1d 趋势与 EMA 排列完全一致，一致性得分 1.00，1d EMA50 斜率 6.12% 最强，日线放量支持上行结构。保留意见有两点：一是 1d ', '{"label": "trending_up", "summary": "同意规则标签 trending_up：1h/4h/1d 趋势与 EMA 排列完全一致，一致性得分 1.00，1d EMA50 斜率 6.12% 最强，日线放量支持上行结构。保留意见有两点：一是 1d 波动率高、布林带宽分位 89，属高波动下的上行；二是短周期动量已钝化（1h 收益为负、MACD 柱微负），与 4h/1d 背离。故判为趋势上行，但非平稳趋势，追涨风险偏高。预测模型不可用；新闻、情绪、链上、资金费率、持仓量未接入。", "evidenceIds": ["ev:alignment", "ev:regime", "ev:momentum:1h", "ev:momentum:4h", "ev:vol:1d", "ev:volume:1d", "ev:volume:1h"], "effectOnSignals": "多周期趋势一致（1h/4h/1d 均 up，EMA 排列 bullish），趋势跟随类信号在此结构下相对有效；但 4h %B=1.01、1d %B=0.99 显示价格贴近上轨，1h MACD 柱微负、1h 近 1/5/20 根收益为负，追涨型入场的新增空间受限。均值回归类信号逆着三周期上行做空缺乏支撑，且日线放量上行（159% 均量）会加大逆势风险；仅在短周期动量钝化与上轨附近出现回撤时，回归信号才具备触发条件，不宜作为主判据。"}', NULL, '{ev:alignment,ev:regime,ev:momentum:1h,ev:momentum:4h,ev:vol:1d,ev:volume:1d,ev:volume:1h}');
INSERT INTO public."AnalysisStep" VALUES ('cmumusggm000fjstinlydpmah', 'b30258dc-5563-4547-98a9-d17b1a01db78', 'bull_research', 8, '多头研究 Agent', 'completed', '2026-09-29 15:51:03.852', '2026-09-29 15:51:06.633', 2781, '5 条证据 · 5 条失效条件', '{"evidence": ["多周期趋势一致上行，1h/4h/1d 均为 up 且 EMA 排列 bullish，一致性得分 1.00", "1d EMA50 斜率 6.12% 最强，价格 0.2305 位于 1h EMA20/50/200 上方，属趋势结构", "4h MACD 柱 0.0016、1d MACD 柱 0.0031 为正，中长周期动量仍偏多", "日线放量：最近一根成交量为 20 根均量 158.08%，1/5/20 根收益 +7.74%/+15.04%/+23.87%", "下方 0.2225（4h 触碰 6 次）与 0.2157（1h 触碰 35 次）构成近端支撑参考"], "evidenceIds": ["ev:alignment", "ev:regime", "ev:trend:1d", "ev:volume:1d", "ev:momentum:4h", "ev:momentum:1d", "lv:4h:0", "lv:1h:0", "ev:momentum:1h", "lv:1h:4"], "invalidation": ["1h 转下并跌破 1h EMA20/50，多周期一致性得分由 1.00 下降", "日线收盘失守 0.2225（4h 触碰 6 次的支撑），趋势结构受损", "4h 与 1d MACD 柱由正转负，中长周期动量同步走弱", "放量上行被反向放量下跌替代，日线量能优势消失", "1d 跌破 EMA20 0.2033，日线趋势标签不再为 up"], "confirmations": ["1h MACD 柱由 -0.0000 转正，且 1h 1/5/20 根收益由负转正", "价格有效站稳并收于近端阻力 0.2307 之上", "上破 0.2345 后 4h 与 1h 量能跟随（当前仅约 19%–21% 均量）", "回踩 0.2225 附近不破并伴随缩量止跌", "4h %B 由 1.01 回落至轨道内后再上行，避免持续贴上轨"]}', NULL, '{ev:alignment,ev:regime,ev:trend:1d,ev:volume:1d,ev:momentum:4h,ev:momentum:1d,lv:4h:0,lv:1h:0,ev:momentum:1h,lv:1h:4}');
INSERT INTO public."AnalysisStep" VALUES ('cmumusggo000gjsticztealhn', 'b30258dc-5563-4547-98a9-d17b1a01db78', 'bear_research', 9, '空头研究 Agent', 'completed', '2026-09-29 15:51:06.665', '2026-09-29 15:51:17.195', 10530, '5 条证据 · 1 轮辩论', '{"evidence": ["1h 近 1/5/20 根收益 -0.82%/-0.43%/-0.17% 均为负，短周期已回吐，与 4h/1d 正收益相悖", "1h MACD 柱 -0.000034 微负、RSI 56.1 中性，短周期动量先行钝化，与 4h/1d 正柱背离", "4h %B=1.01、1d %B=0.99 贴/超布林上轨；1d RSI 68.5、带宽分位 89，追涨回撤风险偏高", "1h/4h 成交量仅 20 根均量的 19.03%/20.80%，日线 158% 放量未获短周期量能确认", "近端阻力 0.2307 距现价仅 +0.09%；快照价 0.2305 高于用户区间上限 0.22，需跌约 4.56%"], "evidenceIds": ["ev:volume:1h", "ev:momentum:1h", "ev:vol:4h", "ev:vol:1d", "ev:volume:4h", "lv:1h:3", "ev:target_range", "ev:momentum:1d"], "invalidation": ["价格收于 0.2307 上方并上破 0.2345，同时 1h/4h 量能明显放大", "1h MACD 柱由微负转正，1h 1/5/20 根收益由负转正，短周期动能修复", "回踩 0.2225 不破、缩量止跌后重新上行，支撑承接有效", "4h 与 1d MACD 柱维持正值，多周期一致性得分继续为 1.00", "1d 稳居 EMA20 0.2033 上方，日线趋势标签继续为 up"], "confirmations": ["1h 收盘跌破 EMA20 0.2282 与 EMA50 0.2236，且 1h MACD 柱持续为负", "1h RSI14 下穿 50，1h 1/5/20 根收益延续负值，短周期弱势延续", "4h 与 1d 收盘跌破 0.2225（4h 触碰 6 次）支撑，结构由支撑转为压制", "4h 与 1d MACD 柱由正转负，中长周期动量与短周期同步走弱", "价格自 4h %B 1.01、1d %B 0.99 回落至轨道内，并伴随放量下行"]}', NULL, '{ev:volume:1h,ev:momentum:1h,ev:vol:4h,ev:vol:1d,ev:volume:4h,lv:1h:3,ev:target_range,ev:momentum:1d}');
INSERT INTO public."AnalysisStep" VALUES ('cmumusggq000hjstihtlaumnx', 'b30258dc-5563-4547-98a9-d17b1a01db78', 'research_synthesis', 10, '研究汇总 Agent', 'completed', '2026-09-29 15:51:17.241', '2026-09-29 15:51:41.514', 24273, 'uncertain · wait_confirmation', '{"outlook": "uncertain", "conflicts": ["1h/4h/1d 趋势一致向上，但 1h MACD 柱微负且近 1/5/20 根收益为负，短周期与中长周期背离。", "日线成交量放大至 20 根均量 158%，但 1h/4h 成交量仅约 19%–21% 均量，量能未向下传导。", "4h 与 1d 的 %B 接近或触及布林上轨，存在追涨回撤风险，与趋势跟随信号形成冲突。", "价格贴近 0.2307 阻力且高于用户观察区间上限 0.22，短期上行空间可能受限。", "量化预测不可用，市场方向判断缺乏概率模型支持，进一步降低置信度。"], "rationale": "多周期趋势一致上行且日线放量，构成偏多结构；但短周期动量已钝化、价格贴近布林上轨与近端阻力，且高于用户观察区间上限，短期追涨风险升高。量化预测不可用，多空证据冲突明显，暂无法给出方向性结论。", "evidenceIds": ["ev:alignment", "ev:volume:1d", "ev:momentum:1h", "ev:vol:4h", "ev:target_range"], "confidenceNote": "数据完整无警告；量化预测不可用，新闻、情绪、链上、资金费率、持仓量均未接入。结论仅基于历史技术面快照，置信度有限，后续需等待短周期动能与量能确认。", "recommendation": "wait_confirmation"}', NULL, '{ev:alignment,ev:volume:1d,ev:momentum:1h,ev:vol:4h,ev:target_range}');
INSERT INTO public."AnalysisStep" VALUES ('cmumusggt000ijsti4j4qgmyt', 'b30258dc-5563-4547-98a9-d17b1a01db78', 'trade_scenarios', 11, '交易情景 Agent', 'completed', '2026-09-29 15:51:41.533', '2026-09-29 15:51:49.89', 8357, '3 个情景', '{"scenarios": [{"name": "突破近端阻力后跟随做多", "condition": "1h 收盘有效站上近端阻力并回踩不破，且短周期量能回暖确认突破有效；当前量能仅为均量约两成。", "direction": "long", "stopLevelId": "lv:4h:0", "invalidation": "价格重新跌回 lv:1h:3 下方并失守 lv:4h:0，或突破伴随量能持续萎缩，视为结构失效。", "entryLevelIds": ["lv:1h:3"], "targetLevelIds": ["lv:1h:4", "lv:1h:5", "lv:1d:3"]}, {"name": "回踩 4h 支撑承接做多", "condition": "价格回落至 4h 支撑附近止跌企稳，且 1h 动能由钝化转为改善，多周期上行结构未破。", "direction": "long", "stopLevelId": "lv:1h:0", "invalidation": "1h 收盘失守 lv:1h:0，表明回调升级为趋势转弱，多头情景不再成立。", "entryLevelIds": ["lv:4h:0"], "targetLevelIds": ["lv:1h:3", "lv:1h:4"]}, {"name": "区间内观望等待确认", "condition": "价格在近端阻力与 4h 支撑之间震荡，短周期量能与动能均未确认，日线与 4h 已接近布林上轨。", "direction": "none", "stopLevelId": null, "invalidation": "若有效突破 lv:1h:4 或跌破 lv:4h:0，则转为方向性情景重新评估。", "entryLevelIds": [], "targetLevelIds": []}]}', NULL, '{}');
